'use strict';
const $=s=>document.querySelector(s),main=$('#main'),A=window.PoeticsAtlas;let E;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let game,view='map',chosen='wor',query='',city='all',until=2026,kind='all',toastTimer;let worldTimer=null,worldRunning=false,gameBusy=false,lastActivity='',lastAction='',currentPlace='home';const reduceMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;let saveAvailable=true;
function initializeGame(){if(game)return;E=window.PoeticsEngine;game=E.create();try{const raw=localStorage.getItem('poetics-fiction-v1');if(raw){const parsed=JSON.parse(raw);if(E.valid(parsed))game=parsed;else saveAvailable=false;}}catch{saveAvailable=false;}}
let routeRun=0;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6500);}function save(){try{localStorage.setItem('poetics-fiction-v1',JSON.stringify(game));return true;}catch{saveAvailable=false;toast('Device storage is unavailable. Download your save to keep progress.');return false;}}
function download(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function route(){const run=++routeRun;main.classList.remove('atlas-brand');stopWorld();const r=location.hash.replace('#/','').split('?')[0]||'home';document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.hash==='#/'+r)a.setAttribute('aria-current','page');});const openAtlas=async()=>{main.innerHTML='<p class="route-loading" role="status">Loading Atlas data from Supabase…</p>';try{if(!window.PoeticsSupabaseAtlas)throw Error('Supabase Atlas client is unavailable.');let snapshot;try{snapshot=await window.PoeticsSupabaseAtlas.read();}catch(e){};if(!snapshot||!snapshot.rows||snapshot.rows.length===0){snapshot={rows:A.records.map(r=>({id:r.id,name:r.name,category:r.type==='Person'?'People':['Place','Venue'].includes(r.type)?'Places':'Platforms',city:r.city,summary:r.description,status:r.status||'Source-supported metadata'})),edges:A.edges.map(e=>({a:e[0],b:e[1],label:e[2]}))};};if(run!==routeRun)return;window.PoeticsDirectoryData.replaceSnapshot(snapshot);window.renderDirectory(main);window.PoeticsAtlasUI?.enforce();}catch(error){if(run!==routeRun)return;main.innerHTML='<section class="page-top"><h1>The Atlas could not load.</h1><p>Supabase is unavailable. No bundled Atlas records have been displayed. Check your connection and try again.</p><button id="retry-atlas">Try again</button></section>';$('#retry-atlas').onclick=route;console.warn('Poetics Supabase Atlas read failed; no bundled snapshot displayed.',error);}};if(r==='atlas'||r==='home')await openAtlas();else if(r==='games'){main.innerHTML='<p class="route-loading" role="status">Loading your poetry world…</p>';try{await window.PoeticsLoadGames();if(run!==routeRun)return;initializeGame();if(!localStorage.getItem('poetics-fiction-v1')){characterCreation();}else{games();if(location.hash.includes('?phone'))openPhone();}}catch{if(run!==routeRun)return;main.innerHTML='<section class="page-top"><h1>The Games could not load.</h1><p>Your saved journey is unchanged. Check your connection and try again.</p><button id="retry-games">Try again</button> <a href="#/atlas">Back to the Atlas</a></section>';$('#retry-games').onclick=route;}}else if(r==='about'||r==='archive'||r==='research')window.renderPoeticsAbout(main);else if(r==='submit')window.renderContribute(main);else home();main.focus({preventScroll:true});window.scrollTo(0,0);}
function home(){main.innerHTML=`<section class="quiet-home"><p class="quiet-kicker">A Vic’Adex concept</p><h1>Poetry.<br>People.<br><em>Possibilities.</em></h1><p class="quiet-intro">Explore Nigerian spoken word.<br>Or step into a poetry world of your own.</p><div class="quiet-paths"><a href="#/atlas"><span>Explore the Atlas</span></a><a href="#/games"><span>Enter the Games</span></a></div></section>`;}

function filtered(){return A.records.filter(r=>(city==='all'||r.city===city)&&(kind==='all'||r.type===kind)&&(r.year===null||r.year<=until)&&(r.name+' '+r.description+' '+r.city).toLowerCase().includes(query.toLowerCase()));}
function profile(){const r=A.records.find(x=>x.id===chosen)||A.records[0],s=A.sources[r.source];const links=A.edges.filter(e=>e[0]===r.id||e[1]===r.id);return `<div class="profile panel"><span class="badge">${esc(r.status||"Source-supported metadata")}</span><span class="badge">${esc(r.type)}</span><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><p class="caption">${esc(r.city)} · ${r.year??'Date not established'}${r.year?' · Year precision only':''} · documented activity, not residence</p><h3>Connections</h3><div class="connections">${links.map(e=>{let id=e[0]===r.id?e[1]:e[0];let n=A.records.find(x=>x.id===id);return `<button data-record="${id}">${esc(e[2])} ${esc(n.name)} </button>`;}).join('')||'<p>No reviewed connections yet.</p>'}</div><h3 style="margin-top:25px">Evidence & permissions</h3><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} </a><p class="caption">Accessed ${s.accessed}. ${esc(s.scope)}</p><p class="caption">${esc(r.rights)}</p><p class="caption">${esc(r.locator||s.locator||'Published page')} · ${esc(r.dateMeaning||'Year precision as described above.')}</p><a href="#/research">Prepare a correction </a></div>`;}
function geography(){const places=A.placeCoordinates;const place=places[city];let bbox='2.5,4,14.7,14.5',marker='';if(place){bbox=[place.lon-.7,place.lat-.5,place.lon+.7,place.lat+.5].join(',');marker='&marker='+place.lat+','+place.lon;}const url='https://www.openstreetmap.org/export/embed.html?bbox='+encodeURIComponent(bbox)+'&layer=mapnik'+marker;return `<iframe class="live-map" title="Interactive OpenStreetMap of ${esc(place?city:'Nigeria')}; use map controls to pan and zoom" src="${url}" loading="lazy" referrerpolicy="no-referrer"></iframe><div class="map-places"><button data-city="all">Nigeria</button><button data-city="Ogbomoso">Ogbomoso</button>${Object.keys(places).filter(x=>x!=="Ogbomoso").map(x=>`<button data-city="${esc(x)}">${esc(x)}</button>`).join("")}<button data-city="Online">Online</button></div><p class="caption">Map © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>. City-centre locators, not venue pins: <a href="https://www.geonames.org/search.html?country=NG&q=${encodeURIComponent(place?city:"Nigeria")}" target="_blank" rel="noopener">GeoNames</a>. Only documented activity appears in the directory. Map loading needs internet.</p>`;}

function atlas(){const rows=filtered();main.innerHTML=`<div class="page-top"><h1>Atlas.</h1><p>A small, evidence-linked window into the ecosystem. Explore documented and announced activity across several Nigerian cities. Coverage is still uneven.</p><div class="notice">${A.records.length} source-linked records · ${A.edges.length} relationships · ${Object.keys(A.sources).length} sources. Independent corroboration, wider coverage and historical editorial review are pending.</div><div class="toolbar"><label class="search">Search records<input id="search" value="${esc(query)}" placeholder="A person, platform or place…"></label><label>Place<select id="city">${['all',...new Set(A.records.map(r=>r.city))].map(x=>`<option value="${x}" ${x===city?'selected':''}>${x==='all'?'All places':x}</option>`).join('')}</select></label><label>Record type<select id="kind">${['all',...new Set(A.records.map(x=>x.type))].map(x=>`<option ${x===kind?'selected':''} value="${x}">${x==='all'?'All types':x}</option>`).join('')}</select></label><label>Up to year <span id="yearLabel">${until}</span><input id="year" type="range" min="2010" max="2026" value="${until}"></label><button id="clear">Reset filters</button></div><p class="caption">Undated records remain visible when filtering years; no dates are inferred.</p></div><div class="workspace"><div class="tabs" aria-label="Atlas view">${['map','network','timeline'].map(v=>`<button data-view="${v}" aria-pressed="${view===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><div class="atlas-layout"><div class="panel">${view==='map'?geography():view==='timeline'?`<div class="timeline">${rows.filter(r=>r.year).sort((a,b)=>a.year-b.year).map(r=>`<button data-record="${r.id}"><b>${r.year}</b><h3>${esc(r.name)}</h3><span class="caption">${esc(r.description)}</span></button>`).join('')||'<p>No dated records match.</p>'}</div>`:`<div class="network">${A.edges.filter(e=>rows.some(r=>r.id===e[0])&&rows.some(r=>r.id===e[1])&&(e[4]===null||e[4]<=until)).map(e=>`<div class="network-edge"><button data-record="${e[0]}">${esc(A.records.find(r=>r.id===e[0]).name)}</button><span>${esc(e[2])}<br>${e[4]??'undated'} · <a href="${A.sources[e[3]].url}" target="_blank" rel="noopener">evidence </a></span><button data-record="${e[1]}">${esc(A.records.find(r=>r.id===e[1]).name)}</button></div>`).join('')||'<p>No reviewed relationships match these filters.</p>'}</div><p class="caption">Connected network, rendered as readable links. Each relationship carries its own source and date precision.</p>`}</div><div><p class="caption" role="status">${rows.length} matching records</p><div class="results">${rows.map(r=>`<button class="record ${r.id===chosen?'selected':''}" data-record="${r.id}"><span>${esc(r.name)}<small>${esc(r.type)} / ${esc(r.city)}</small></span><span>${r.year??'Undated'} </span></button>`).join('')||'<p>No records match. Reset or broaden your search.</p>'}</div></div></div><div id="profile">${profile()}</div></div>`;
$('#search').oninput=e=>{query=e.target.value;const start=e.target.selectionStart;atlas();$('#search').focus();$('#search').setSelectionRange(start,start);};$('#city').onchange=e=>{city=e.target.value;atlas();};$('#kind').onchange=e=>{kind=e.target.value;atlas();};$('#year').oninput=e=>{until=+e.target.value;$('#yearLabel').textContent=until;};$('#year').onchange=()=>atlas();$('#clear').onclick=()=>{query='';city='all';kind='all';until=2026;atlas();};main.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;atlas();});bindAtlas();}
function bindAtlas(){main.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{chosen=b.dataset.record;$('#profile').innerHTML=profile();main.querySelectorAll('.record').forEach(x=>x.classList.toggle('selected',x.dataset.record===chosen));bindAtlas();$('#profile').scrollIntoView({behavior:'auto',block:'nearest'});});main.querySelectorAll('[data-city]').forEach(b=>b.onclick=e=>{e.preventDefault();city=b.dataset.city;atlas();});}
function games(){main.innerHTML=`<div class="page-top"><h1>Your poetry life.</h1><p>Write a miniature about a journey. Share it with the poetry wall, sharpen it for the stage, or spend a day getting to know the room.</p></div><div class="workspace"><div class="game-banner">FICTIONAL WORLD / JANUARY 2010 / All characters, posts, venues, events and prices are invented. No historical activity is implied.</div><div class="game-head"><button class="notifications-button" data-notifications>Notifications <span>${noticeCount()}</span></button><h2>Day ${game.day} · ${esc(game.city)}</h2><div class="small-actions"><button id="rest">Rest & advance day</button><button id="work">Paid shift · +₦450</button></div></div><div class="world-clock"><div><span class="clock-dot ${worldRunning?'running':''}"></span><span id="world-state">${worldRunning?'World playing':'World paused'}</span><span class="caption"> · one day every 12 seconds</span></div><button id="world-toggle" aria-pressed="${worldRunning}">${worldRunning?'Pause world':'Play world'}</button></div><div class="visual-neighbourhood">${window.PoeticsWorld(esc(game.city))}</div><details class="activity-details"><summary>Around the room</summary><div id="live-activity" aria-live="polite">${lastActivity||'Play the world to follow the community.'}</div></details><div class="stats">${[['Energy',game.energy+'/100'],['Funds','₦'+game.money.toLocaleString()],['Craft',game.craft],['Delivery',game.delivery],['Reputation',game.reputation]].map(([l,v])=>`<div class="stat">${l}<strong>${v}</strong></div>`).join('')}</div><div class="game-layout"><div><section class="panel" id="writing-studio"><div class="eyebrow">Challenge 01 / A journey, in a pocket</div><h3>Write the thing you carried.</h3><p class="caption">Choose a concrete object, a place and something left unsaid. Your writing stays on this device. Posting shares it only inside this local simulation.</p><label>Pen name<input id="penname" maxlength="40" value="${esc(game.name)}"></label><label style="margin-top:18px">Your original poem<textarea id="poem" maxlength="4000" placeholder="The bus left before the rain…">${esc(game.poem)}</textarea></label><p class="caption"><span id="chars">${game.poem.length}</span> / 4,000 characters · Device save ${saveAvailable?'available':'unavailable — download a save'}</p><div class="small-actions"><button id="draft">Save draft</button><button class="primary" data-action="post">Post to wall · 12 energy</button><button data-action="coach">Coach · ₦350 / 18 energy</button><button data-action="rehearse">Rehearse · 16 energy</button></div><details><summary>Craft notebook & game mechanics</summary><p class="caption">Try one vivid image, a deliberate pause and an ending that leaves room. Coaching is authored rule-based advice; no AI service is called. Competition points use word count, skill, preparation, delivery choice, fictional opponent research and seeded chance. They cannot measure literary quality.</p></details></section><section class="panel" id="poetry-wall" style="margin-top:22px"><div class="eyebrow">The poetry wall / Fictional posts</div><div class="wall-heading"><h3>A little room on the internet.</h3><button data-phone>Open on your phone </button></div><div class="wall">${game.wall.length?game.wall.map(p=>`<article class="post ${p.day===game.day?'fresh-post':''}"><strong>${esc(p.author)} · Day ${p.day}</strong><p>${esc(p.text)}</p><span class="caption">${p.author===game.name?'Your original writing / local simulation':'Authored fictional miniature'}</span></article>`).join(''):'<p>The wall is quiet. Post your poem, or advance a day to see the community at work.</p>'}</div></section><section class="panel" style="margin-top:22px"><h3>Your event journal</h3><div class="log" aria-label="Simulation history">${game.log.map(x=>`<p>${esc(x)}</p>`).join('')}</div></section></div><aside><section class="panel" id="performance-room"><div class="eyebrow">Tonight / Lion’s Lines</div><h3>A microphone. A choice.</h3><p class="caption">Open mic: build confidence without a ranking. Slam: compete with three fictional poets. Minimum draft: 40 characters.</p><label>Delivery approach<select id="delivery"><option value="intimate">Intimate / craft-led</option><option value="rhythmic">Rhythmic / delivery-led</option><option value="balanced">Balanced</option></select></label><div class="small-actions"><button data-action="openmic">Open mic · ₦150 / 20 energy</button><button data-action="research">Research rivals · ₦200 / 10 energy</button><button class="primary" data-action="slam">Enter slam · ₦400 / 25 energy</button></div><p class="caption">Preparation ${game.prepared}/5 · Research ${game.research}/3 · One slam per day. A win earns a fictional ₦700 prize.</p></section><details class="panel community" style="margin-top:22px"><summary>The community · 12 poets</summary><p class="caption">Each day advances all twelve characters’ independent plans. Exchange feedback to build relationships.</p>${game.npcs.map(n=>`<article class="npc"><h3>${esc(n.name)} <span class="caption">/ ${esc(n.style)}</span></h3><p>${esc(n.activity)}<br>Goal: ${n.goal} · Bond ${n.relationship} · Works ${n.works}</p><button data-feedback="${n.id}">Exchange feedback · 10 energy</button>${n.memory.length?`<p class="caption">Remembers: ${esc(n.memory.at(-1))}</p>`:''}</article>`).join('')}</details><section class="panel" style="margin-top:22px"><h3>The fictional circuit</h3><label>Destination<select id="destination">${['Ogbomoso','Ibadan','Lagos'].map(x=>`<option ${x===game.city?'selected':''}>${x}</option>`).join('')}</select></label><div class="small-actions"><button data-action="travel">Travel · ₦600 / 20 energy</button></div><p class="caption">Destinations change the scene label in this slice; city-specific events are a future feature. Travel prices are game balancing values.</p><a class="btn" href="#/atlas">Explore the separate historical Atlas </a></section></aside></div><div class="small-actions"><button id="export">Download game save</button><label class="btn">Import your save<input id="import" type="file" accept="application/json" style="display:block;width:220px;padding:4px"></label><button id="reset">Reset this fictional journey</button></div><p class="caption">No accounts, public posting or cross-device cloud saves in this prototype. The world runs while this page is active and you choose Play. It pauses when you leave or hide the page. Saves remain on this device.</p></div>`;
window.Poetics3D.mount();bindNoticeButtons();main.querySelectorAll("[data-open-map]").forEach(b=>b.onclick=()=>window.PoeticsMap.open());main.querySelectorAll('[data-phone]').forEach(b=>b.onclick=openPhone);main.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>visitPlace(b.dataset.place));if($('.player-avatar'))$('.player-avatar').dataset.at=currentPlace;$('#poem').oninput=e=>{$('#chars').textContent=e.target.value.length;E.act(game,'write',e.target.value);save();};$('#penname').onchange=e=>{E.act(game,'name',e.target.value);save();};$('#draft').onclick=()=>{E.act(game,'write',$('#poem').value);toast(save()?'Draft saved on this device.':'Use Download game save to preserve your draft.');};async function action(type,arg){if(gameBusy)return;E.act(game,'write',$('#poem').value);E.act(game,'name',$('#penname').value);const before=structuredClone(game);const result=E.act(game,type,arg);if(!result.ok){toast(result.message);return;}save();lastAction=type;if(type==='rest'||type==='work')lastActivity=activityMarkup(before);if(type==='openmic'||type==='slam'){await perform(result.message,type);if(location.hash.split('?')[0]!=='#/games')return;}const expanded=$('.community')?.open;games();if(expanded)$('.community').open=true;animateStats(before);toast(result.message);}$('#world-toggle').onclick=()=>{worldRunning?stopWorld():startWorld();syncClock();};$('#rest').onclick=()=>action('rest');$('#work').onclick=()=>action('work');main.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.action==='slam'?$('#delivery').value:b.dataset.action==='travel'?$('#destination').value:undefined));main.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>action('feedback',+b.dataset.feedback));$('#export').onclick=()=>download('poetics-fiction-day-'+game.day+'.json',JSON.stringify(game,null,2));$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>500000){toast('That save is too large. Maximum 500 KB.');return;}try{const candidate=JSON.parse(await file.text());if(!E.valid(candidate))throw Error();game=candidate;save();games();toast('Fictional journey restored.');}catch{toast('Invalid or incompatible save. Your current journey is unchanged.');}};$('#reset').onclick=()=>{if(confirm('Reset this journey? Download your save first if you want to keep it.')){game=E.create();save();games();toast('A new fictional journey begins.');}};}
function visitPlace(place){currentPlace=place;window.Poetics3D.go(place);const player=$('.player-avatar');if(player)player.dataset.at=place;const names={home:'Under-Verse Court: your fictional student compound.',studio:'LadoTech Studio: write and rehearse.',stage:'Lion’s Lines: prepare, perform or enter the slam.',work:'VerseMart: take a paid shift to earn ₦450.',underg:'Under-G · community district. Placement adapted for play.',gate:'LAUTECH Gate · campus entrance. Placement adapted for play.',adenike:'Adenike · student neighbourhood. Placement adapted for play.',general:'General · neighbourhood. Placement adapted for play.'};$('#place-status').textContent=names[place];const targets={home:'#rest',studio:'#writing-studio',stage:'#performance-room',work:'#work',underg:'#poetry-wall',gate:'#world-help',adenike:'#writing-studio',general:'#work'};let enter=$('#enter-place');if(!enter){enter=document.createElement('button');enter.id='enter-place';$('#place-status').after(enter);}enter.textContent={home:'Rest at home',studio:'Open notebook',stage:'Enter Lion’s Lines',work:'Take a paid shift',underg:'Open poetry wall',gate:'Open district map',adenike:'Open notebook',general:'Take a paid shift'}[place];enter.onclick=()=>{if(place==='underg'){openPhone();return;}if(place==='gate'){window.PoeticsMap.open();return;}const target=$(targets[place]);if(!target)return;if(place==='home'||place==='work'||place==='general')target.click();else target.scrollIntoView({behavior:reduceMotion()?'auto':'smooth',block:'center'});};}
function phoneFeed(){return game.wall.length?game.wall.map(p=>`<article class="phone-post"><div class="phone-author"><span class="avatar">${esc(p.author[0])}</span><span>${esc(p.author)}<small>Day ${p.day} · fictional community</small></span></div><p>${esc(p.text)}</p></article>`).join(''):'<p class="caption phone-empty">The wall is quiet. Write a poem or play the world to hear from the community.</p>';}
function refreshPhone(){const feed=$('#phone-feed');if(feed)feed.innerHTML=phoneFeed();const day=$('#phone-day');if(day)day.textContent='Day '+game.day;document.querySelectorAll('[data-notifications] span').forEach(b=>b.textContent=noticeCount());refreshNotices();}
function openPhone(){if($('#poetics-phone'))return;const phone=document.createElement('dialog');phone.id='poetics-phone';phone.className='phone-dialog';phone.setAttribute('aria-label','In-game phone: poetry wall');phone.innerHTML=`<div class="phone-shell"><div class="phone-status"><span id="phone-day">Day ${game.day}</span><button data-notifications class="phone-notices">Alerts <span>${noticeCount()}</span></button><button id="phone-close" aria-label="Close phone">×</button></div><div class="phone-app-head"><h2>The poetry wall.</h2><p>A little room on the internet.</p></div><div class="phone-scroll"><div id="phone-feed">${phoneFeed()}</div></div><form id="phone-compose"><label for="phone-draft">Your original poem</label><textarea id="phone-draft" maxlength="4000" placeholder="Leave a few lines in the room…">${esc(game.poem)}</textarea><div class="phone-compose-actions"><span class="caption">12 energy to post</span><button class="primary" type="submit">Post poem</button></div><p class="caption">Fictional community. Saved only on this device.</p></form></div>`;document.body.append(phone);phone.showModal();bindNoticeButtons();const close=()=>{phone.close();phone.remove();};$('#phone-close').onclick=close;phone.addEventListener('cancel',e=>{e.preventDefault();close();});$('#phone-draft').oninput=e=>{E.act(game,'write',e.target.value);save();const draft=$('#poem');if(draft)draft.value=e.target.value;const chars=$('#chars');if(chars)chars.textContent=e.target.value.length;};$('#phone-compose').onsubmit=e=>{e.preventDefault();E.act(game,'write',$('#phone-draft').value);const result=E.act(game,'post');if(result.ok){save();games();refreshPhone();$('.phone-scroll').scrollTop=0;}toast(result.message);};}
function activityMarkup(previous){return game.npcs.filter((n,i)=>n.activity!==previous.npcs[i].activity||n.works!==previous.npcs[i].works).slice(0,3).map(n=>`<p class="activity-item"><span class="avatar">${esc(n.name[0])}</span><span><strong>${esc(n.name)}</strong><small>${esc(n.activity)}</small></span></p>`).join('')||'<p class="caption">The poets quietly revise their drafts.</p>';}
function syncClock(){const b=$('#world-toggle');if(!b)return;b.textContent=worldRunning?'Pause world':'Play world';b.setAttribute('aria-pressed',String(worldRunning));$('#world-state').textContent=worldRunning?'World playing':'World paused';$('.clock-dot').classList.toggle('running',worldRunning);}
function stopWorld(){clearInterval(worldTimer);worldTimer=null;worldRunning=false;syncClock();}
function startWorld(){if(worldTimer)return;worldRunning=true;worldTimer=setInterval(()=>{if(document.hidden||gameBusy||location.hash.split('?')[0]!=='#/games'){if(document.hidden||location.hash.split('?')[0]!=='#/games')stopWorld();return;}const previous=structuredClone(game);E.tick(game);lastActivity=activityMarkup(previous);save();const expanded=$('.community')?.open;const active=document.activeElement;const editing=active?.id==='poem'||active?.id==='penname';const selection=editing?[active.id,active.selectionStart,active.selectionEnd]:null;const scroll=window.scrollY;games();if(expanded)$('.community').open=true;if(selection){const field=$('#'+selection[0]);field.focus({preventScroll:true});field.setSelectionRange(selection[1],selection[2]);}window.scrollTo(0,scroll);animateStats(previous);refreshPhone();},12000);syncClock();}
function animateStats(previous){if(reduceMotion())return;const keys=['energy','money','craft','delivery','reputation'];main.querySelectorAll('.stat').forEach((el,i)=>{if(previous[keys[i]]!==game[keys[i]])el.animate([{opacity:.4,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'ease-out'});});}
async function perform(message,type){gameBusy=true;const dialog=document.createElement('dialog');dialog.className='performance-dialog';dialog.setAttribute('aria-label','Fictional '+(type==='slam'?'slam performance':'open mic performance'));dialog.innerHTML=`<button class="close-performance" aria-label="Skip performance animation">Skip</button><div class="eyebrow">${type==='slam'?'Fictional slam':'Fictional open mic'}</div><h2>${esc(game.name)} takes the mic.</h2><div class="performance-lines">${game.poem.split(/\n/).filter(Boolean).slice(0,4).map((line,i)=>`<p style="--line:${i}">${esc(line)}</p>`).join('')}</div><div class="applause" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p class="performance-result" role="status">${esc(message)}</p><button class="primary continue-performance">Back to the room</button>`;document.body.append(dialog);dialog.showModal();await new Promise(resolve=>{let timer;const finish=()=>{clearTimeout(timer);dialog.close();dialog.remove();gameBusy=false;resolve();};dialog.querySelector('.close-performance').onclick=finish;dialog.querySelector('.continue-performance').onclick=finish;dialog.addEventListener('cancel',e=>{e.preventDefault();finish();});timer=setTimeout(()=>{dialog.classList.add('resolved');},reduceMotion()?0:3500);});}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopWorld();});
window.addEventListener('hashchange',route);window.addEventListener('popstate',route);route();

window.addEventListener("keydown",e=>{if(e.key.toLowerCase()==="m"&&location.hash.split("?")[0]==="#/games"&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)&&!document.querySelector("dialog[open]")){e.preventDefault();window.PoeticsMap?.open();}});

function noticeCount(){return window.PoeticsOpportunities.list(game).filter(n=>n.unread&&(n.result||(game.day<=n.deadline&&!n.submitted))).length;}
function bindNoticeButtons(){document.querySelectorAll('[data-notifications]').forEach(b=>b.onclick=openNotices);}
function noticeCards(){const O=window.PoeticsOpportunities,items=O.list(game);return items.map(n=>{const expired=game.day>n.deadline;const labels={openmic:'Open mic',slam:'Slam',competition:'Writing competition',anthology:'Anthology'};const desc={openmic:'Share a poem with the room. ₦150 · 20 energy.',slam:'Compete with fictional poets. ₦400 · 25 energy.',competition:'Submit an original poem. ₦250 · 20 energy. Fictional prize: ₦500.',anthology:'Submit to an invented collection. Free · 10 energy.'};return `<article class="notice-card ${n.unread?'unread':''}"><div class="notice-card-meta"><span>${labels[n.type]}</span><span>${n.result?'Result · day '+n.result.day:n.submitted?'Submitted':expired?'Closed':'Closes day '+n.deadline}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.result?n.result.message:desc[n.type])}</p><div class="small-actions">${!expired&&!n.submitted?`<button class="primary" data-notice-action="${n.id}" data-notice-type="${n.type}">${n.type==='anthology'||n.type==='competition'?'Submit your poem':'Go to performance'}</button><button data-notice-prepare="${n.id}">Prepare a poem</button>`:''}<button data-notice-read="${n.id}">${n.unread?'Mark read':'Read'}</button></div></article>`;}).join('');}
function refreshNotices(){const panel=$('#notification-cards');if(panel){panel.innerHTML=noticeCards();wireNotices();}}
function wireNotices(){const O=window.PoeticsOpportunities;const close=()=>{const d=$('#notification-dialog');d?.close();d?.remove();};document.querySelectorAll('[data-notice-read]').forEach(b=>b.onclick=()=>{O.markRead(game,b.dataset.noticeRead);save();refreshNotices();document.querySelectorAll('[data-notifications] span').forEach(x=>x.textContent=noticeCount());});document.querySelectorAll('[data-notice-prepare]').forEach(b=>b.onclick=()=>{O.markRead(game,b.dataset.noticePrepare);save();close();const phone=$('#poetics-phone');if(phone)$('#phone-draft').focus();else $('#writing-studio').scrollIntoView({behavior:reduceMotion()?'auto':'smooth',block:'center'});});document.querySelectorAll('[data-notice-action]').forEach(b=>b.onclick=()=>{const type=b.dataset.noticeType,id=b.dataset.noticeAction;if(type==='openmic'||type==='slam'){O.markRead(game,id);save();close();const phone=$('#poetics-phone');if(phone){phone.close();phone.remove();}$('#performance-room').scrollIntoView({behavior:reduceMotion()?'auto':'smooth',block:'center'});return;}const result=O.submit(game,id);if(result.ok){save();games();refreshPhone();}toast(result.message);});}
function openNotices(){if($('#notification-dialog'))return;const d=document.createElement('dialog');d.id='notification-dialog';d.className='notification-dialog';d.setAttribute('aria-label','Fictional poetry opportunities');d.innerHTML=`<div class="map-dialog-head"><h2>Opportunities</h2><button id="close-notifications" aria-label="Close notifications">×</button></div><p class="caption">Fictional in-game calls · simulated deadlines · new calls every seven days. These are not live event announcements.</p><div id="notification-cards">${noticeCards()}</div><p class="caption">Submitted poems stay on this device. Outcomes use game rules; they are not literary verdicts or real-world publication.</p>`;document.body.append(d);d.showModal();$('#close-notifications').onclick=()=>{d.close();d.remove();};d.addEventListener('cancel',e=>{e.preventDefault();d.close();d.remove();});wireNotices();}


function characterCreation(){
  stopWorld();
  const seed = Date.now();
  const defaultCity = E.pickRandomOrigin ? E.pickRandomOrigin(seed) : 'Jos';
  
  main.innerHTML = `<div class="page-top"><h1>Step into the Poetic Atlas</h1><p>Every voice begins with a quiet draft before finding a stage.</p></div><section class="panel" style="max-width:680px;margin:24px auto;padding:28px;"><div class="eyebrow">Character Creation / Fictional Nigerian Poetry World</div><h2 style="margin-top:8px;">Your Starting Journey</h2><p class="caption">Choose your pen name and starting origin. Most voices begin in regional Tier 3 writing circles before traveling to major circuits.</p><form id="creation-form" style="display:flex;flex-direction:column;gap:18px;margin-top:20px;"><label><strong>Pen Name</strong><input id="create-name" maxlength="40" value="New voice" required style="width:100%;margin-top:6px;padding:8px 12px;font-size:16px;"></label><label><strong>Starting Town & Literary Circuit</strong><select id="create-city" style="width:100%;margin-top:6px;padding:8px 12px;font-size:15px;"><optgroup label="Tier 3: Regional Communities & Workshop Circles (Recommended)"><option value="Jos" ${defaultCity==='Jos'?'selected':''}>Jos — Acoustic calm, cool mountain air, conscious circles</option><option value="Calabar" ${defaultCity==='Calabar'?'selected':''}>Calabar — Coastal lyricism, festival warmth</option><option value="Maiduguri" ${defaultCity==='Maiduguri'?'selected':''}>Maiduguri — Resilient verse, desert dusk</option><option value="Zaria" ${defaultCity==='Zaria'?'selected':''}>Zaria — University arts, student circles</option><option value="Gombe" ${defaultCity==='Gombe'?'selected':''}>Gombe — Savannah rhythm, patient market observations</option><option value="Ibadan" ${defaultCity==='Ibadan'?'selected':''}>Ibadan — Literary heritage, premier university classical verse</option><option value="Aba" ${defaultCity==='Aba'?'selected':''}>Aba — Vibrant trade center, working-class lines</option></optgroup><optgroup label="Tier 2: Established Regional Hubs"><option value="Kano" ${defaultCity==='Kano'?'selected':''}>Kano — Griot traditions, deliberate cadence</option><option value="Abuja" ${defaultCity==='Abuja'?'selected':''}>Abuja — National stages, institutional festivals</option><option value="Enugu" ${defaultCity==='Enugu'?'selected':''}>Enugu — Coal city grit, folkloric cadence</option></optgroup><optgroup label="Tier 1: Major Performance Circuits"><option value="Lagos" ${defaultCity==='Lagos'?'selected':''}>Lagos — Commercial slams, street hustle, high crowd stakes</option><option value="Ogbomoso" ${defaultCity==='Ogbomoso'?'selected':''}>Ogbomoso — LAUTECH workshops, Words on Rampage archive</option></optgroup></select></label><label><strong>Game Clock Pacing</strong><select id="create-speed" style="width:100%;margin-top:6px;padding:8px 12px;font-size:15px;"><option value="slow">Story Pace (30s / day) — Plenty of room to read calls & revise</option><option value="normal" selected>Normal Pace (15s / day) — Balanced simulation rhythm</option><option value="fast">Fast Pace (8s / day) — Rapid calendar advance</option></select></label><div style="background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.1);padding:14px;border-radius:6px;"><strong>Initial Path: The Page Poet</strong><p class="caption" style="margin:4px 0 0 0;">Everyone starts writing quietly on the page. Attending local open mics will unlock Spoken Word and tournament Slams as teachable moments.</p></div><button type="submit" class="primary" style="padding:12px;font-size:16px;cursor:pointer;margin-top:8px;">Begin Poetry Life</button></form></section>`;

  $('#creation-form').onsubmit = e => {
    e.preventDefault();
    const name = $('#create-name').value.trim() || 'New voice';
    const chosenCity = $('#create-city').value;
    const speed = $('#create-speed').value;
    game = E.create(seed);
    game.name = name;
    game.city = chosenCity;
    game.speed = speed;
    if (game.persona && game.persona.history) {
      game.persona.history[0].note = 'Begun on the Page in ' + chosenCity + ' with a quiet notebook.';
    }
    game.log = ['You arrive in the fictional ' + chosenCity + ' poetry community, January 2010.'];
    save();
    games();
  };
}